private static void dfs(char[][] grid, int x, int y, HashSet<String> visited) {
    if (x < 0 || x >= grid.length || y < 0 || y >= grid[x].length || grid[x][y] == '*') return;

    if (visited.contains(x + "," + y)) return;

    visited.add(x + "," + y);

    dfs(grid, x + 1, y, visited);
    dfs(grid, x - 1, y, visited);
    dfs(grid, x, y + 1, visited);
    dfs(grid, x, y - 1, visited);
}
