public static String appx(String word1, String word2) {
    String error = "Error: The words must be at least two characters long.";
    if (word1.length() < 2 || word2.length() < 2) {
        return error;
    }

    int commonLetters = 0;
    for (int i = 0; i < word1.length(); i++) {
        for (int j = 0; j < word2.length(); j++) {
            if (word1.charAt(i) == word2.charAt(j)) {
                commonLetters++;
                break;
            }
        }
    }

    double numerator = commonLetters;
    double denominator = word1.length() + word2.length() - 1;

    // Reduce the fraction to its simplest form
    int gcd = gcd(numerator, denominator);
    numerator /= gcd;
    denominator /= gcd;

    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

private static int gcd(int a, int b) {
    if (b == 0) {
        return a;
    }
    return gcd(b, a % b);
}
