public int minTime(int n, int[][] edges, boolean[] hasApple) {
    List<List<Integer>> graph = new ArrayList<>(n);
    for(int i=0; i<n; i++) graph.add(new ArrayList<>());
    for(int[] edge : edges) {
        graph.get(edge[0]).add(edge[1]);
        graph.get(edge[1]).add(edge[0]);
    }

    boolean[] visited = new boolean[n];
    Map<Integer, Integer> appleTime = new HashMap<>();
    minTimeRecursion(0, graph, visited, hasApple, appleTime);

    return appleTime.getOrDefault(0, 0);
}

private void minTimeRecursion(int node, List<List<Integer>> graph, boolean[] visited, boolean[] hasApple, Map<Integer, Integer> appleTime) {
    visited[node] = true;

    int alternateTime = 0;
    for(int child : graph.get(node)) {
        if(!visited[child]) {
            minTimeRecursion(child, graph, visited, hasApple, appleTime);
            alternateTime = Math.max(alternateTime, appleTime.getOrDefault(child, 0) - 2);
        }
    }

    if(hasApple[node]) {
        alternateTime += 2;
    }

    if(alternateTime != 0) {
        appleTime.put(node, alternateTime);
    }
}
