public String sortString(String s) {
    StringBuilder sb = new StringBuilder();
    while (s.length() > 0) {
        char smallestChar = smallestChar(s);
        sb.append(smallestChar);
        s = removeChar(s, smallestChar);
        if (s.length() == 0) {
            break;
        }

        char largestChar = largestChar(s);
        sb.append(largestChar);
        s = removeChar(s, largestChar);
    }
    return sb.toString();
}

private char smallestChar(String s) {
    char smallest = Character.MAX_VALUE;
    for (char c : s.toCharArray()) {
        if (c < smallest) {
            smallest = c;
        }
    }
    return smallest;
}

private char largestChar(String s) {
    char largest = Character.MIN_VALUE;
    for (char c : s.toCharArray()) {
        if (c > largest) {
            largest = c;
        }
    }
    return largest;
}

private String removeChar(String s, char c) {
    StringBuilder sb = new StringBuilder();
    for (char ch : s.toCharArray()) {
        if (ch != c) {
            sb.append(ch);
        }
    }
    return sb.toString();
}
