    int result = 0; // Tracks the minimum number of insertions needed

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            balance++;
        } else {
            balance--;
            if (balance < 0) {
                // A necessary '(' at this position would create an imbalance
                // So, 1 insertion is needed here to balance it
                result++;
                balance++;
