            while (!stack.isEmpty() && heights[i] <= heights[stack.peek()]) {
                stack.pop();
            }
            if (stack.isEmpty()) {
                left smaller[i] = -1;
            } else {
                left smaller[i] = stack.peek();
            }
            stack.push(i);
        }

        stack.clear();

        // Find the index of the first smaller element to the right of each index
        for (int i = heights.length - 1; i >= 0; i--) {
            while (!stack.isEmpty() && heights[i] <= heights[stack.peek()]) {
                stack.pop();
            }
            if (stack.isEmpty()) {
                right smaller[i] = heights.length;
            } else {
                right smaller[i] = stack.peek();
            }
            stack.push(i);
        }

        int maxArea = 0;

