public static int findSmallestInteger(int n) {
    if (n == 0) return 0; // No smallest integer can be formed if n is 0.

    // Convert the number to a character array
    char[] digits = Integer.toString(n).toCharArray();
    int length = digits.length;
    int[] indices = new int[length];
    int[] perm = new int[length];

    // Fill the indices array
    for (int i = 0; i < length; i++) {
        indices[i] = i;
    }

    // Generate all permutation starting from the smallest number
    for (int i = 1; i < length; i++) {
        perm[i] = indices[i];
    }

    while (true) {
        int val = createNumberFromPermutation(perm, digits);
        if (val > n) {
            // Found the smallest integer greater than n
            return val;
        }
        // Move to the next permutation
        incrementPermutation(perm);
    }
}

public static int createNumberFromPermutation(int[] perm, char[] digits) {
    int number = 0;
    for (int i : perm) {
        number = number * 10 + digits[i];
    }
    return number;
}

public static void incrementPermutation(int[] perm) {
    int i = perm.length - 1;
    while (i > 0 && perm[i - 1] >= perm[i]) {
        i--;
    }
    if (i == 0) {
        // If the input is the largest permutation, return -1
        return;
    }
    int j = perm.length - 1;
    while (perm[j] <= perm[i - 1]) {
        j--;
    }
    swap(perm, i - 1, j);
    Arrays.sort(perm, i, perm.length);
}
